package proj

// sweep_extra_test.go — AI-B's extension sweep: an independent point set beyond
// the frozen golden_*.json grids (structured edges + seeded LCG), generated by
// xcheck/gen_sweep.py from pyproj 3.8.0 / PROJ 9.8.1. Owner: AI-B.
//
// Purpose: the golden fixtures repeat one fixed 33x33 grid per CRS; if an
// implementation accidentally fit that grid, nothing would notice. This sweep
// exercises every projection through the full public path
// (Parse → NewProjection → Forward/Inverse) on fresh points, including each
// projection's domain edges.
//
// Tolerances: COORDINATION §2.5 with the C#3 forward relative floor and the
// C#9 inverse relative floor (the sweep contains 1e9 m-scale probes).
// The reference file is ordinary JSON, so this test runs WITHOUT pyproj.

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

type sweepCase struct {
	CRS      string         `json:"crs"`
	Forward  []sweepRec     `json:"forward"`
	Inverse  []sweepRec     `json:"inverse"`
	Specials []sweepSpecial `json:"specials"`
}

type sweepRec struct {
	Lon, Lat, X, Y float64
	// pyproj's own forward-then-inverse round trip. N.B. the JSON keys carry
	// underscores; Go's case-insensitive field match does NOT ignore them,
	// so these two need explicit tags.
	RtLon float64 `json:"rt_lon"`
	RtLat float64 `json:"rt_lat"`
}

type sweepSpecial struct {
	Desc      string  `json:"desc"`
	Lon       float64 `json:"lon"`
	Lat       float64 `json:"lat"`
	X         float64 `json:"x"`
	Y         float64 `json:"y"`
	ExpectNaN bool    `json:"expectNaN"`
}

type sweepFile struct {
	Generator string               `json:"generator"`
	Generated string               `json:"generated"`
	Note      string               `json:"note"`
	Cases     map[string]sweepCase `json:"cases"`
}

// loadSweep reads xcheck/sweep_extra.json (path relative to this source file).
func loadSweep(t *testing.T) sweepFile {
	t.Helper()
	_, file, _, _ := runtime.Caller(0)
	path := filepath.Join(filepath.Dir(file), "xcheck", "sweep_extra.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read sweep: %v (run: python xcheck/gen_sweep.py)", err)
	}
	var s sweepFile
	if err := json.Unmarshal(raw, &s); err != nil {
		t.Fatalf("parse sweep: %v", err)
	}
	return s
}

// sweepInvTol is the C#9 inverse relative floor: extreme probes (1e9 m) have a
// radian-longitude ulp far above the 1e-9 deg absolute gate.
func sweepInvTol(x float64) float64 {
	return math.Max(1e-9, math.Abs(x)*2e-21)
}

// TestSweepExtra runs every projection in the extension sweep through the full
// contract path and against fresh pyproj references.
func TestSweepExtra(t *testing.T) {
	s := loadSweep(t)
	t.Logf("sweep generator: %s (%s)", s.Generator, s.Generated)

	for _, name := range []string{"latlong", "eqc", "geos_x", "geos_y", "stere",
		"stere_eq", "stere_obl", "laea", "laea_eq", "laea_np", "laea_sp",
		"lcc", "merc", "tmerc", "aeqd_np", "aeqd_sp", "aeqd_eq", "aeqd_obl",
		"aeqd_sph", "utm", "utm_south", "merc_km"} {
		c, ok := s.Cases[name]
		if !ok {
			t.Fatalf("sweep case %q missing", name)
		}
		crs, err := Parse(c.CRS)
		if err != nil {
			t.Fatalf("%s: Parse(%q): %v", name, c.CRS, err)
		}
		p, err := crs.NewProjection()
		if err != nil {
			t.Fatalf("%s: NewProjection: %v", name, err)
		}

		maxFwd, maxInv := 0.0, 0.0
		for _, r := range c.Forward {
			x, y, err := p.Forward(r.Lon, r.Lat)
			if err != nil {
				t.Fatalf("%s: Forward(%v, %v): %v", name, r.Lon, r.Lat, err)
			}
			// latlong's x/y are DEGREES (identity): the dateline 180 vs -180
			// is the same point, so compare x circularly there (D5, same rule
			// as A's xcheck consumer and the C#5 fixture note).
			d := math.Max(math.Abs(y-r.Y), 0)
			if degX := strings.Contains(c.CRS, "latlong"); degX {
				if e := lonDiff(x, r.X); e > d {
					d = e
				}
			} else {
				if e := math.Abs(x - r.X); e > d {
					d = e
				}
			}
			if d > tol(r.X) && d > tol(r.Y) {
				t.Fatalf("%s: forward mismatch at (%v, %v): got (%.6f, %.6f) want (%.6f, %.6f)",
					name, r.Lon, r.Lat, x, y, r.X, r.Y)
			}
			if d > maxFwd {
				maxFwd = d
			}
			// Round trip through our own inverse. The gate is "consistent with
			// pyproj's own round trip" (rt_lon/rt_lat in the reference): at the
			// projection periphery even PROJ's own F-then-I drifts (measured:
			// tmerc at 70 deg from the central meridian drifts 1.4e-8 deg in
			// BOTH implementations), so an absolute 1e-9 deg gate would be
			// unachievable there — same call as C#7, recorded as C#13. For
			// well-conditioned points pyproj's rt is the input itself, so this
			// reduces to the §2.5 absolute gate.
			lon, lat, err := p.Inverse(x, y)
			if err != nil {
				continue // domain-edges are only asserted one-way here
			}
			if lonDiff(lon, r.RtLon) > 1e-9 || math.Abs(lat-r.RtLat) > 1e-9 {
				t.Fatalf("%s: round trip (%v, %v) -> (%.10f, %.10f), pyproj's own round trip is (%.10f, %.10f)",
					name, r.Lon, r.Lat, lon, lat, r.RtLon, r.RtLat)
			}
		}

		for _, r := range c.Inverse {
			lon, lat, err := p.Inverse(r.X, r.Y)
			if err != nil {
				t.Fatalf("%s: Inverse(%v, %v): %v", name, r.X, r.Y, err)
			}
			lonNorm := geoNormLon(lon)
			d := math.Max(lonDiff(lonNorm, r.Lon), math.Abs(lat-r.Lat))
			if d > sweepInvTol(r.X) {
				t.Fatalf("%s: inverse mismatch at (%v, %v): got (%.10f, %.10f) want (%.10f, %.10f)",
					name, r.X, r.Y, lonNorm, lat, r.Lon, r.Lat)
			}
			if d > maxInv {
				maxInv = d
			}
		}

		for _, r := range c.Specials {
			if !r.ExpectNaN {
				continue
			}
			if r.X != 0 || r.Y != 0 {
				lon, lat, err := p.Inverse(r.X, r.Y)
				if !errorsIsDomain(err) || !math.IsNaN(lon) || !math.IsNaN(lat) {
					t.Fatalf("%s: expected ErrDomain/NaN for %s, got (%v, %v, %v)",
						name, r.Desc, lon, lat, err)
				}
				continue
			}
			if _, _, err := p.Forward(r.Lon, r.Lat); !errorsIsDomain(err) {
				t.Fatalf("%s: expected ErrDomain for %s, got %v", name, r.Desc, err)
			}
		}

		t.Logf("%-8s %3d forward (max %.3e m), %3d inverse (max %.3e deg), %d specials",
			name, len(c.Forward), maxFwd, len(c.Inverse), maxInv, len(c.Specials))
	}
}

// TestThreadSafety smoke-checks the frozen "all Projections are immutable and
// thread-safe" contract (§2.5): one instance hammered from many goroutines must
// return exactly the serial results. The race detector itself needs cgo
// (unavailable on this Windows box); this test still catches shared-state bugs
// and panics on any platform, and `go test -race` on linux CI completes it.
func TestThreadSafety(t *testing.T) {
	s := loadSweep(t)
	const workers = 8

	for _, name := range []string{"stere", "stere_eq", "stere_obl", "laea",
		"laea_eq", "laea_np", "laea_sp", "lcc", "merc", "tmerc",
		"aeqd_obl", "aeqd_np", "utm"} {
		c := s.Cases[name]
		crs, err := Parse(c.CRS)
		if err != nil {
			t.Fatalf("%s: Parse: %v", name, err)
		}
		p, err := crs.NewProjection()
		if err != nil {
			t.Fatalf("%s: NewProjection: %v", name, err)
		}
		// Serial reference through the same points (forward AND inverse).
		type pt struct{ lon, lat, x, y, blon, blat float64 }
		var refs []pt
		for _, r := range c.Forward[:12] {
			x, y, err := p.Forward(r.Lon, r.Lat)
			if err != nil {
				t.Fatalf("%s: Forward: %v", name, err)
			}
			bl, ba, err := p.Inverse(x, y)
			if err != nil {
				t.Fatalf("%s: Inverse: %v", name, err)
			}
			refs = append(refs, pt{r.Lon, r.Lat, x, y, bl, ba})
		}
		refs2 := append([]pt(nil), refs...)

		errs := make(chan error, workers)
		for w := 0; w < workers; w++ {
			go func() {
				defer func() {
					if r := recover(); r != nil {
						errs <- fmt.Errorf("panic: %v", r)
					}
				}()
				for i := 0; i < 200; i++ {
					for j := range refs {
						r := refs[j]
						x, y, err := p.Forward(r.lon, r.lat)
						if err != nil {
							errs <- err
							return
						}
						if x != r.x || y != r.y {
							errs <- fmt.Errorf("concurrent forward drift at %d", j)
							return
						}
						lon, lat, err := p.Inverse(refs2[j].x, refs2[j].y)
						if err != nil {
							errs <- err
							return
						}
						if lonDiff(lon, refs2[j].blon) > 1e-9 || math.Abs(lat-refs2[j].blat) > 1e-9 {
							errs <- fmt.Errorf("concurrent inverse drift at %d", j)
							return
						}
					}
				}
				errs <- nil
			}()
		}
		for w := 0; w < workers; w++ {
			if err := <-errs; err != nil {
				t.Fatalf("%s: concurrent use: %v", name, err)
			}
		}
	}
}
